import{_ as t,o,c as a,a3 as i}from"./chunks/framework._FWOmmqu.js";const u=JSON.parse('{"title":"Live Chat (developer)","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Live Chat (developer) | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/live-chat"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Live Chat (developer) | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/live-chat"}]]},"headers":[],"relativePath":"developer-guide/live-chat.md","filePath":"developer-guide/live-chat.md","lastUpdated":1789669215000}'),d={name:"developer-guide/live-chat.md"};function c(s,e,n,r,l,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="live-chat-developer" tabindex="-1">Live Chat (developer) <a class="header-anchor" href="#live-chat-developer" aria-label="Permalink to &quot;Live Chat (developer)&quot;">​</a></h1><p>Free Communication module (<code>live-chat</code> <strong>1.4.1</strong>). Public widget traffic resolves the workspace by widget <code>public_key</code> (central/web routes), initializes tenancy, checks entitlement, then ends tenancy — same pattern as custom Lead webhooks.</p><h2 id="surfaces" tabindex="-1">Surfaces <a class="header-anchor" href="#surfaces" aria-label="Permalink to &quot;Surfaces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>Auth</th></tr></thead><tbody><tr><td><code>GET/POST /api/public/live-chat/{publicKey}/…</code></td><td>Widget key + visitor Bearer session token (SHA-256 hashed at rest)</td></tr><tr><td><code>/api/tenant/v1/live-chat/…</code></td><td><code>auth:tenant-api</code> + <code>module:live-chat</code> + Spatie <code>can:</code></td></tr><tr><td><code>public/widgets/live-chat.js</code></td><td>Static embed script (<code>data-key</code>, <code>data-api-base</code>) — Tawk-style FAB/panel in a <strong>Shadow DOM</strong> host</td></tr><tr><td>SPA <code>/live-chat</code></td><td>Agent desk tabs: Overview / Inbox / Live visitors</td></tr><tr><td>SPA <code>/settings?tab=live-chat</code></td><td>Widget / departments / canned replies (<code>live-chat.manage</code>)</td></tr></tbody></table><p>Throttle: <code>live-chat-widget</code> (60/min by IP + key) and <code>live-chat-widget-session</code> (10/min for session create); disabled in testing. CSRF excepted for <code>api/public/live-chat/*</code>.</p><p><strong>CORS:</strong> <code>LiveChatPublicCors</code> reflects <code>Origin</code> for credential-less public widget paths only (does not open the rest of the API).</p><p><strong>Public DTOs:</strong> Visitor responses use <code>LiveChatPublicConversationResource</code> / <code>LiveChatPublicMessageResource</code> — uuid/status/body/direction/attachment meta/timestamps only (no assignee, Lead, visitor IP, sender email, or <code>direction=note</code>).</p><p><strong>Sessions:</strong> Expire after 7 days from creation. Regenerating the public key (or deactivating the widget / cancelling the module) revokes all visitor session hashes. Retention: <code>live-chat:purge-visitors --days=90</code> (daily). Banned visitors (<code>is_banned</code>) cannot create sessions or send messages.</p><p><strong>Embed resume (1.4.1):</strong> The widget persists <code>session_token</code> / conversation hints in <code>localStorage</code> keyed by public key. On load it validates via <code>POST …/heartbeat</code> (which returns <code>open_conversation_uuid</code> when an open thread exists), then hydrates both visitor and agent messages. Host-page CSS cannot restyle the pre-chat form because UI lives in Shadow DOM with explicit dark labels/input colors.</p><h2 id="branding-hours-offline-presence" tabindex="-1">Branding, hours, offline, presence <a class="header-anchor" href="#branding-hours-offline-presence" aria-label="Permalink to &quot;Branding, hours, offline, presence&quot;">​</a></h2><p>Widget settings store <code>primary_color</code>, <code>launcher_text</code>, <code>position</code>, <code>header_title</code>, <code>logo_url</code>, <code>offline_*</code>, <code>business_hours</code>, <code>email_notify_agents</code>, <code>default_department_id</code>, <code>suggested_replies</code>, <code>show_powered_by</code>, <code>agent_display_name</code>. Bootstrap returns branding plus <code>within_hours</code> / <code>accepting_live</code> and optional Reverb public realtime hints. Outside hours (or inactive accepting), visitors leave offline messages when <code>offline_enabled</code>.</p><p><code>POST …/heartbeat</code> (Bearer session) updates <code>last_seen_at</code>, <code>page_url</code>, <code>referrer</code>, UA-derived <code>browser</code>/<code>os</code>, optional country from CDN headers, and <code>pages_viewed</code>. Tenant <code>GET …/visitors/live</code> and <code>GET …/stats</code> power the Live visitors + Overview tabs. Presence broadcasts throttle on the inbox channel as <code>LiveChatVisitorPresence</code>.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>Agent <code>POST …/messages</code> accepts <code>as_note=true</code> (<code>LiveChatMessageDirectionEnum::Note</code>). Notes are returned on tenant message lists and never on public visitor polls or broadcast visitor payloads.</p><h2 id="realtime" tabindex="-1">Realtime <a class="header-anchor" href="#realtime" aria-label="Permalink to &quot;Realtime&quot;">​</a></h2><p>Agent channels (distinct from Team Chat):</p><ul><li><code>private-tenant.{tenantId}.live-chat.inbox</code></li><li><code>private-tenant.{tenantId}.live-chat.conversation.{uuid}</code></li></ul><p>Visitor public channel: <code>live-chat.visitor.{uuid}</code> (UUID secrecy). Events: <code>LiveChatMessageSent</code>, <code>LiveChatConversationUpdated</code>, <code>LiveChatVisitorPresence</code> (<code>ShouldBroadcastNow</code>). Embed keeps short-poll fallback.</p><h2 id="soft-leads-help-desk" tabindex="-1">Soft Leads / Help Desk <a class="header-anchor" href="#soft-leads-help-desk" aria-label="Permalink to &quot;Soft Leads / Help Desk&quot;">​</a></h2><p><code>PATCH …/conversations/{id}</code> with <code>lead_id</code> calls <code>LiveChatConversationService::linkLead</code>. Requires Leads entitled; null unlinks.</p><p><code>POST …/conversations/{id}/escalate</code> creates a Help Desk ticket (<code>source: live-chat</code>) when Help Desk is entitled and sets <code>help_desk_ticket_id</code>. Escalation transcript omits notes.</p><h2 id="canned-replies-departments" tabindex="-1">Canned replies &amp; departments <a class="header-anchor" href="#canned-replies-departments" aria-label="Permalink to &quot;Canned replies &amp; departments&quot;">​</a></h2><p>Tenant CRUD under <code>/live-chat/canned-replies</code> and <code>/live-chat/departments</code> (<code>manage</code> writes, <code>view</code> lists).</p><h2 id="automation" tabindex="-1">Automation <a class="header-anchor" href="#automation" aria-label="Permalink to &quot;Automation&quot;">​</a></h2><p>Wired triggers: <code>live_chat.conversation_opened</code>, <code>live_chat.message_inbound</code>, <code>live_chat.conversation_closed</code> — fan-out via <code>IntegrationEventDispatcher</code>.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p><code>LiveChatInboundMessageNotification</code> (<code>live-chat.inbound</code>) → recipients with <code>live-chat.view</code> (assignee-scoped when assigned). Optional email when <code>email_notify_agents</code> is true.</p><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><p>Pest: <code>tests/Feature/Tenant/LiveChat/</code>. Playwright: <code>npm run test:e2e:live-chat</code>.</p><p>Production readiness: <a href="/deployment/live-chat-production-readiness">Live Chat production readiness</a>.</p>',30)])])}const v=t(d,[["render",c]]);export{u as __pageData,v as default};
